void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Image
    vec4 img = texture(iChannel0, uv);

    // Gaussians
    float o = 1.0;
    float gr0 = gaussian(0.0, o);
    float gr1 = gaussian(1.0, o);
    float grsq2 = gaussian(1.41421, o);

    // Dir Guassian Blurs
    float b1 = greyscale(texture(iChannel0, uv-vec2(1.0,1.0)/iResolution.xy)) * grsq2;
    float b2 = greyscale(texture(iChannel0, uv-vec2(0.0,1.0)/iResolution.xy)) * gr1;
    float b3 = greyscale(texture(iChannel0, uv-vec2(1.0,-1.0)/iResolution.xy)) * grsq2;
    float b4 = greyscale(texture(iChannel0, uv-vec2(1.0,0.0)/iResolution.xy)) * gr1;
    float b5 = greyscale(texture(iChannel0, uv-vec2(0.0,0.0)/iResolution.xy)) * gr0;
    float b6 = greyscale(texture(iChannel0, uv-vec2(-1.0,0.0)/iResolution.xy)) * gr1;
    float b7 = greyscale(texture(iChannel0, uv-vec2(-1.0,-1.0)/iResolution.xy)) * grsq2;
    float b8 = greyscale(texture(iChannel0, uv-vec2(0.0,-1.0)/iResolution.xy)) * gr1;
    float b9 = greyscale(texture(iChannel0, uv-vec2(1.0,-1.0)/iResolution.xy)) * grsq2;

    // combine blurs
    float bf = sqrt(pow(pow2s(b1)+b2+b3+b4+pow2s(b5)+b6+b7+b8+pow2s(b9),2.0) + pow(b1+pow2s(b2)+b3+b4+pow2s(b5)+b6+b7+pow2s(b8)+b9,2.0) + pow(b1+b2+pow2s(b3)+b4+pow2s(b5)+b6+pow2s(b7)+b8+b9,2.0) + pow(b1+b2+b3+pow2s(b4)+pow2s(b5)+pow2s(b6)+b7+b8+b9,2.0));

    // Output to screen w/ Tonemapping
    // 1.1963~=sqrt(pi)/(2*sqrt(2*pi))+erf(1/o)
    fragColor = img/greyscale(img)*bf/(pow(4.0+o/2.0,1.1963));
}
